    "plt.xlabel('Loan Approved')\n",
    "plt.ylabel('Count')\n",
    "\n",
    "# Pie Chart\n",
    "plt.subplot(1, 2, 2)\n",
    "counts.plot(kind='pie', autopct='%1.1f%%', colors=['skyblue', 'salmon'], startangle=140)\n",
    "plt.title('Class Balance (Pie Chart)')\n",
    "plt.ylabel('')\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.show()"
